// AC: @ui-task-board ac-4
test('active fleet row shows last few lines of output from WebSocket', async ({
	page,
	daemon
}) => {
	const mockAgentStatus = {
		dispatch_enabled: true,
		active_invocations: [
			{
				session_id: 'test-session-002',
				agent_id: 'task-worker',
				task_ref: '@01KG0RR8CB8N4YGP991WD7XS9R',
				elapsed_ms: 30000
			}
		],
		queue_depth: 0,
		agent_definitions: [
			{ id: 'task-worker', name: 'Task Worker', adapter: 'claude-agent-acp' }
		]
	};

	await page.route('**/api/agent/status', async (route) => {
		await route.fulfill({
			status: 200,
			contentType: 'application/json',
			body: JSON.stringify(mockAgentStatus)
		});
	});

	await page.goto('/tasks/board');
	await expect(page.getByTestId('board-columns')).toBeVisible();
	await expect(page.getByTestId('active-fleet-row')).toBeVisible();

	// Initially output should show empty placeholder
	const fleetCard = page.getByTestId('fleet-card');
	await expect(page.getByTestId('fleet-output-empty')).toBeVisible();
	await expect(page.getByTestId('fleet-output-empty')).toHaveText(/Awaiting output/);

	// Simulate WebSocket agent_text_chunk by dispatching a MessageEvent
	// on the page's active WebSocket connection
	await page.evaluate((sessionId) => {
		const sockets = (window as any).__playwright_sockets__ ?? [];
		// Find open WebSocket by iterating global WebSocket instances
		// Fallback: dispatch on all open WebSockets
		const allWs: WebSocket[] = [];
		const originalWs = WebSocket;
		// Access any WebSocket the page has opened
		for (const ws of (window as any).__kspec_ws_instances__ ?? []) {
			if (ws.readyState === originalWs.OPEN) {
				allWs.push(ws);
			}
		}
		if (allWs.length === 0) return false;

		const msg = JSON.stringify({
			msg_id: 'test-output-001',
			seq: 9999,
			timestamp: new Date().toISOString(),
			topic: 'agents',
			event: 'agent_text_chunk',
			data: {
				session_id: sessionId,
				text: 'Running tests...\nAll 25 tests passed\nBuild complete'
			}
		});
		allWs[0].dispatchEvent(new MessageEvent('message', { data: msg }));
		return true;
	}, 'test-session-002');

	// Verify the output lines rendered
	const outputEl = page.getByTestId('fleet-output');
	await expect(outputEl).toBeVisible({ timeout: 5000 });
	await expect(outputEl).toContainText('Running tests...');
	await expect(outputEl).toContainText('All 25 tests passed');
	await expect(outputEl).toContainText('Build complete');

	// Verify aria-live for accessibility
	await expect(outputEl).toHaveAttribute('aria-live', 'polite');
});

