node -e "
const { execSync, spawnSync } = require('child_process');
const { mkdirSync, cpSync, rmSync, existsSync, writeFileSync } = require('fs');
const { join } = require('path');
const { tmpdir } = require('os');
const { createServer } = require('net');

async function main() {
  // Get available port
  const port = await new Promise((resolve, reject) => {
    const server = createServer();
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => {
      const addr = server.address();
      const p = addr.port;
      server.close(() => resolve(p));
    });
  });

  const tempDir = join(tmpdir(), 'kspec-debug-' + Date.now());
  const kspecDir = join(tempDir, '.kspec');
  mkdirSync(kspecDir, { recursive: true });

  const isolatedHome = join(tempDir, '.home');
  const configDir = join(isolatedHome, '.config', 'kspec');
  mkdirSync(configDir, { recursive: true });

  // Copy fixtures
  const fixtures = join(__dirname, 'tests/fixtures');
  cpSync(fixtures, kspecDir, {
    recursive: true,
    filter: (src) => !src.includes('test-base') && !src.includes('project-tests')
  });

  // Init git
  execSync('git init', { cwd: tempDir, stdio: 'ignore' });
  execSync('git config user.email \"test@test.com\"', { cwd: tempDir, stdio: 'ignore' });
  execSync('git config user.name \"Test\"', { cwd: tempDir, stdio: 'ignore' });

  // Setup worktree
  const gwd = join(tempDir, '.git', 'worktrees', '-kspec');
  mkdirSync(gwd, { recursive: true });
  writeFileSync(join(kspecDir, '.git'), 'gitdir: ' + gwd + '\n');
  writeFileSync(join(gwd, 'gitdir'), join(tempDir, '.git') + '\n');
  writeFileSync(join(gwd, 'HEAD'), 'ref: refs/heads/kspec-meta\n');

  const env = { ...process.env, HOME: isolatedHome, USERPROFILE: isolatedHome, WEB_UI_DIR: join(__dirname, 'build') };

  // Start daemon
  const r = spawnSync('kspec', ['serve', 'start', '--daemon', '--port', String(port), '--kspec-dir', tempDir], {
    cwd: tempDir, encoding: 'utf-8', env
  });
  if (r.status !== 0) { console.error('Failed:', r.stderr); process.exit(1); }

  // Wait for ready
  for (let i = 0; i < 30; i++) {
    try {
      const resp = await fetch('http://localhost:' + port + '/api/health');
      if (resp.ok) break;
    } catch {}
    await new Promise(r => setTimeout(r, 200));
  }

  // Query task detail
  const resp = await fetch('http://localhost:' + port + '/api/tasks/01KG0RR8CB8N4YGP991WD7XS9R');
  const data = await resp.json();
  console.log('type:', JSON.stringify(data.type));
  console.log('full:', JSON.stringify(data, null, 2));

  // Cleanup
  spawnSync('kspec', ['serve', 'stop', '--kspec-dir', tempDir], { cwd: tempDir, encoding: 'utf-8', env });
  await new Promise(r => setTimeout(r, 500));
  rmSync(tempDir, { recursive: true, force: true });
}

main().catch(e => { console.error(e); process.exit(1); });
